{
  "aktywnosci": [
    {
      "opis": "Nauczyciel rozkłada na dywanie duży arkusz papieru pakowego. Dzieci odrysowują na nim swoje dłonie farbą w różnych kolorach (po jednej dłoni na dziecko). Gdy farba wyschnie, nauczyciel wycina dłonie. Każde dziecko przykleja swoją dłoń na dłuższym pasku papieru (np. brystolu) – tak, by wszystkie tworzyły „łańcuch serc”. Nauczyciel pomaga napisać na górze: „Kochamy Was, Mamusie!”. Praca zostaje zawieszona w sali jako niespodzianka dla mam.",
      "tytul": "Łańcuch dłoni dla mam"
    },
    {
      "opis": "Dzieci siadają w kole z tamburynami, marakasami i dzwoneczkami. Nauczyciel recytuje prosty wierszyk (np. „Moja mama jest kochana, uśmiechnięta i roześmiana, klaszczmy razem, tupnijmy nogą – dla niej dzisiaj gramy wszyscy drogą!”). Dzieci powtarzają rytm i grają na instrumentach – najpierw cicho (gdy mama śpi), potem głośno (gdy mama tańczy). Na koniec każdy mówi jedno zdanie: „Moja mama lubi…”. Zabawę kończy wspólne brawa.",
      "tytul": "Muzyczne życzenia – gramy dla mamy"
    },
    {
      "opis": "Dzieci naśladują czynności, które wykonują z mamą na co dzień: pranie (wycieranie rąk w górę i w dół), gotowanie (mieszanie w garnkach), przytulanie (obejmowanie się w parach), spacer (maszerowanie w rytmie). Nauczyciel prowadzi zabawę: mówi „mama gotuje” – dzieci mieszają rękami, „mama przytula” – wszyscy się tulą do siebie (lub do poduszek). Ćwiczenia łączą ruch z wyobraźnią i wzmacniają więź z bliskimi.",
      "tytul": "Ruchowe „Robimy jak mama”"
    }
  ]
}
